# Scope the token actions to this workload's identity
resource "aws_iam_policy" "<example_resource_name>" {
  name   = "<example_resource_name>"
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = [
        "bedrock-agentcore:GetWorkloadAccessToken",
        "bedrock-agentcore:GetWorkloadAccessTokenForJWT",
      ]
      # FIX: replace '*' with the workload identity this policy is for
      Resource = [
        "arn:aws:bedrock-agentcore:${var.region}:${var.account_id}:workload-identity-directory/default",
        "arn:aws:bedrock-agentcore:${var.region}:${var.account_id}:workload-identity-directory/default/workload-identity/<example_resource_id>",
      ]
    }]
  })
}
